import React, { useState } from 'react';
import './App.css';

// Import màn hình chính và các màn hình con
import HomePage from './components/ui/HomePage';
import ShowtimeScreen from './components/booking/ShowtimeScreen';
import SeatScreen from './components/booking/SeatScreen';
import AuthScreen from './components/auth/AuthScreen';
import ComboScreen from './components/booking/ComboScreen';
import PaymentScreen from './components/booking/PaymentScreen';
import MyTickets from './components/booking/MyTickets';
import AdminPanel from './components/admin/AdminPanel';
import MovieManagement from './components/admin/MovieManagement';
import InfoPage from './components/ui/InfoPage';
import defaultDatabase from './data/database';
import Icon from './components/ui/Icon';

function App() {
  const [users, setUsers] = useState(defaultDatabase.users);
  const [rooms] = useState(defaultDatabase.rooms);
  const [movies, setMovies] = useState(defaultDatabase.movies);
  const [showtimes, setShowtimes] = useState(defaultDatabase.showtimes);
  const [seats] = useState(defaultDatabase.seats);
  const [bookings, setBookings] = useState(defaultDatabase.bookings);

  const [currentUser, setCurrentUser] = useState(null);
  const [currentScreen, setCurrentScreen] = useState('movie-list');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [selectedShowtime, setSelectedShowtime] = useState(null);
  const [comboInfo, setComboInfo] = useState({ comboCounts: {}, comboTotal: 0 });
  const [promoInfo, setPromoInfo] = useState({ type: 'none', valid: true, data: {} });
  const [pendingSelection, setPendingSelection] = useState(null);
  const [paymentResult, setPaymentResult] = useState(null);
  const [authMode, setAuthMode] = useState('login');
  const [statusMessage, setStatusMessage] = useState('');
  const [scrollTarget, setScrollTarget] = useState(null);
  const [adminView, setAdminView] = useState('panel');

  const handleNavigate = (screen, data) => {
    if (screen === 'showtime-list' && data) {
      setSelectedMovie(data);
      setCurrentScreen('showtime-list');
      return;
    }

    if (screen === 'home' || screen === 'movies' || screen === 'genres' || screen === 'deals' || screen === 'contact') {
      setCurrentScreen('movie-list');
      setScrollTarget(screen);
      return;
    }

    if (screen === 'faq' || screen === 'support' || screen === 'terms' || screen === 'privacy') {
      setCurrentScreen(screen);
      return;
    }

    if (screen === 'my-tickets') {
      setCurrentScreen('my-tickets');
      return;
    }

    if (screen === 'admin') {
      setCurrentScreen('admin');
      return;
    }
  };

  const handleLogin = (user) => {
    setCurrentUser(user);
    setCurrentScreen('movie-list');
    setStatusMessage('');
  };

  const handleRegister = (newUser) => {
    const existing = users.find(u => u.email === newUser.email);
    if (existing) {
      setStatusMessage('Email đã tồn tại, vui lòng dùng email khác.');
      return false;
    }
    const createdUser = { ...newUser, id: `u-${Date.now()}` };
    setUsers(prev => [...prev, createdUser]);
    setCurrentUser(createdUser);
    setCurrentScreen('movie-list');
    setStatusMessage('Đăng ký thành công. Chào mừng bạn!');
    return true;
  };

  const handleForgotPassword = (email) => {
    const user = users.find((u) => u.email === email);
    if (!user) {
      setStatusMessage('Không tìm thấy email. Vui lòng kiểm tra lại.');
      return false;
    }
    setStatusMessage(`Mật khẩu của bạn là: ${user.password}`);
    return true;
  };

  const handleAddShowtime = (showtimeData) => {
    setShowtimes(prev => [...prev, showtimeData]);
  };

  const handleCancelBooking = (bookingId) => {
    setBookings(prev => prev.filter(b => b.id !== bookingId));
  };

  const handleCancelOrder = (originalBookingId) => {
    setBookings(prev => prev.filter(b => b.original_booking_id !== originalBookingId));
  };

  return (
    <div className="app-shell">
      <div className="container">
        {currentScreen === 'movie-list' && (
          <HomePage 
            currentUser={currentUser}
            onNavigate={handleNavigate}
            onGoToAuth={() => { setAuthMode('login'); setCurrentScreen('auth'); }}
            onGoToTickets={() => setCurrentScreen('my-tickets')}
            onGoToAdmin={() => setCurrentScreen('admin')}
            onLogout={() => setCurrentUser(null)}
            scrollTarget={scrollTarget}
            onClearScrollTarget={() => setScrollTarget(null)}
          />
        )}

        {currentScreen === 'showtime-list' && (
          <ShowtimeScreen 
            movie={selectedMovie} 
            showtimes={showtimes} 
            rooms={rooms}
            seats={seats}
            bookings={bookings}
            onSelectShowtime={(st) => { 
              setSelectedShowtime(st); 
              setCurrentScreen('seat-plan'); 
            }}
            onBack={() => setCurrentScreen('movie-list')} 
          />
        )}

        {currentScreen === 'seat-plan' && (
          <SeatScreen 
            showtime={selectedShowtime} 
            movie={selectedMovie}
            seats={seats}
            rooms={rooms}
            bookings={bookings}
            onSeatsSelected={(sel) => { setPendingSelection(sel); setCurrentScreen('combo'); }}
            onBack={() => setCurrentScreen('showtime-list')}
          />
        )}

        {currentScreen === 'combo' && (
          <ComboScreen 
            ticketTotal={pendingSelection ? pendingSelection.ticketTotal : 0}
            selectedSeatCount={pendingSelection ? pendingSelection.seat_ids.length : 0}
            onBack={() => setCurrentScreen('seat-plan')}
            onNext={(info) => {
              setComboInfo({ comboCounts: info.comboCounts || {}, comboTotal: info.comboTotal || 0 });
              setPromoInfo(info.promoInfo || { type: 'none', valid: true, data: {} });
              setCurrentScreen('payment');
            }}
          />
        )}

        {currentScreen === 'payment' && (
          <PaymentScreen 
            ticketTotal={pendingSelection ? pendingSelection.ticketTotal : 0}
            comboTotal={comboInfo.comboTotal}
            promoInfo={promoInfo}
            onBack={() => setCurrentScreen('combo')}
            onConfirm={(pay) => {
              const seatIds = (pendingSelection && pendingSelection.seat_ids) || [];
              const groupId = `group-${Date.now()}`;
              const newBookings = seatIds.map(id => ({
                id: Math.random().toString(36).substr(2, 9),
                showtime_id: pendingSelection.showtime_id,
                seat_id: id,
                user_id: currentUser ? currentUser.id : null,
                paid: true,
                paymentMethod: pay.method || null,
                qrCode: pay.qrCode || null,
                original_booking_id: groupId,
                promoType: promoInfo.type,
                promoData: promoInfo.data,
                promoDiscount: pay.discount || 0
              }));
              setBookings([...bookings, ...newBookings]);
              const showtime = showtimes.find(s => s.id === (pendingSelection && pendingSelection.showtime_id));
              setPaymentResult({
                ...pay,
                show_date: showtime?.show_date,
                show_time: showtime?.show_time,
                movieTitle: selectedMovie ? selectedMovie.title : undefined,
                promoInfo: promoInfo
              });
              setPendingSelection(null);
              setPromoInfo({ type: 'none', valid: true, data: {} });
              setComboInfo({ comboCounts: {}, comboTotal: 0 });
              setCurrentScreen('payment-success');
            }}
          />
        )}

        {currentScreen === 'payment-success' && (
          <div
            style={{
              position: 'fixed',
              inset: 0,
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              backgroundColor: 'rgba(15, 23, 42, 0.75)',
              zIndex: 9999,
              padding: '20px',
            }}
          >
            <div
              className="card p-4 shadow-sm border-0"
              style={{
                maxWidth: 520,
                width: '100%',
                background: 'rgba(15, 23, 42, 0.98)',
                border: '1px solid rgba(124, 58, 237, 0.22)',
                borderRadius: 24,
                boxShadow: '0 26px 80px rgba(15, 23, 42, 0.35)',
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 18 }}>
                <div
                  style={{
                    width: 48,
                    height: 48,
                    borderRadius: '50%',
                    background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)',
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    color: '#fff',
                    fontSize: 22,
                    boxShadow: '0 18px 30px rgba(124, 58, 237, 0.25)',
                  }}
                >
                  ✓
                </div>
                <h3 className="fw-bold mb-0" style={{ color: '#c4b5fd' }}>Thanh toán thành công</h3>
              </div>
              <p style={{ color: '#cbd5e1', marginBottom: 24 }}>
                Cảm ơn bạn đã thanh toán. Vé của bạn đã được lưu trong mục "Vé của tôi".
              </p>
              {paymentResult && (paymentResult.movieTitle || paymentResult.show_date) && (
                <div style={{ marginBottom: 12, color: '#cbd5e1' }}>
                  <div className="fw-bold" style={{ color: '#e2e8f0' }}>{paymentResult.movieTitle}</div>
                  <div className="small">Suất: {paymentResult.show_date} • {paymentResult.show_time}</div>
                </div>
              )}
              {paymentResult && paymentResult.qrCode && (
                <div className="mt-3">
                  <div className="fw-bold" style={{ color: '#e2e8f0', marginBottom: 10 }}>Mã QR thanh toán:</div>
                  <div
                    style={{
                      width: '100%',
                      maxWidth: 200,
                      height: 88,
                      background: 'rgba(255, 255, 255, 0.06)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      borderRadius: 16,
                      border: '1px solid rgba(148, 163, 184, 0.16)',
                      color: '#cbd5e1',
                      fontWeight: 700,
                    }}
                    className="mt-2"
                  >
                    QR {paymentResult.qrCode}
                  </div>
                </div>
              )}
              {paymentResult && paymentResult.promoInfo && (
                <div className="mt-3 p-3" style={{ borderRadius: 16, background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(148, 163, 184, 0.12)' }}>
                  <div className="fw-bold" style={{ color: '#e2e8f0', marginBottom: 8 }}>Chi tiết ưu đãi</div>
                  <div className="small text-secondary">Loại ưu đãi: {paymentResult.promoInfo.type || 'Không'}</div>
                  {paymentResult.promoInfo.type === 'student' && (
                    <div className="small text-secondary mt-1">Trường: {paymentResult.promoInfo.data?.student?.school || '---'} • Khóa: {paymentResult.promoInfo.data?.student?.course || '---'}</div>
                  )}
                  {paymentResult.promoInfo.type === 'child' && (
                    <div className="small text-secondary mt-1">Ngày sinh: {paymentResult.promoInfo.data?.child?.birthDate || '---'} • Tuổi: {paymentResult.promoInfo.data?.child?.age ?? '---'}</div>
                  )}
                  {paymentResult.promoInfo.type === 'group' && (
                    <div className="small text-secondary mt-1">Số thành viên: {paymentResult.promoInfo.data?.group?.members?.length || 0}</div>
                  )}
                  {paymentResult.promoInfo.type === 'couple' && (
                    <>
                      <div className="small text-secondary mt-1">Ảnh cặp đôi: {paymentResult.promoInfo.data?.couple?.fileName || 'Chưa chọn'}</div>
                      {paymentResult.promoInfo.data?.couple?.comboAdded && (
                        <div className="small text-secondary mt-1">Tặng thêm: 1 × Combo Bắp lớn + Nước</div>
                      )}
                    </>
                  )}
                  {paymentResult.discount != null && (
                    <div className="small text-success mt-2">Giảm giá: -{paymentResult.discount.toLocaleString()}đ</div>
                  )}
                </div>
              )}
              <div className="d-flex gap-3 flex-wrap mt-4" style={{ justifyContent: 'center' }}>
                <button
                  className="btn fw-bold py-2"
                  style={{
                    background: 'rgba(255, 255, 255, 0.08)',
                    color: '#e2e8f0',
                    borderRadius: 14,
                    minWidth: '150px',
                    border: '1px solid rgba(255,255,255,0.08)',
                  }}
                  onClick={() => setCurrentScreen('movie-list')}
                >
                  Về trang chủ
                </button>
                <button
                  className="btn fw-bold text-white py-2"
                  style={{
                    background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)',
                    borderRadius: 14,
                    minWidth: '150px',
                  }}
                  onClick={() => setCurrentScreen('my-tickets')}
                >
                  Xem Vé Của Tôi
                </button>
              </div>
            </div>
          </div>
        )}

        {currentScreen === 'my-tickets' && (
          <MyTickets
            bookings={bookings}
            movies={movies}
            showtimes={showtimes}
            seats={seats}
            rooms={rooms}
            currentUser={currentUser}
            onCancelBooking={(bookingId) => {
              if (!window.confirm('Bạn có chắc muốn hủy vé này?')) return;
              handleCancelBooking(bookingId);
            }}
            onCancelOrder={(originalBookingId) => {
              if (!window.confirm('Bạn có chắc muốn hủy toàn bộ đơn này? (tất cả ghế sẽ bị hủy)')) return;
              handleCancelOrder(originalBookingId);
            }}
            onBackHome={() => setCurrentScreen('movie-list')}
          />
        )}

        {currentScreen === 'faq' && (
          <InfoPage
            title="Câu Hỏi Thường Gặp"
            subtitle="Các câu hỏi phổ biến về vé, thanh toán và hỗ trợ khách hàng."
            sections={[
              { heading: 'Làm sao để mua vé?', text: 'Bạn có thể chọn phim, suất chiếu và ghế ngay trên trang chủ. Sau đó tiếp tục chọn combo và thanh toán để hoàn tất.' },
              { heading: 'Thanh toán bằng cách nào?', text: 'Ứng dụng hỗ trợ thanh toán MoMo, ZaloPay và mã QR. Chọn phương thức phù hợp khi vào trang thanh toán.' },
              { heading: 'Làm sao xem vé đã mua?', text: 'Sau khi thanh toán thành công, bạn có thể vào mục "Vé của tôi" để xem lại vé và mã QR thanh toán.' },
            ]}
            onBack={() => setCurrentScreen('movie-list')}
          />
        )}

        {currentScreen === 'support' && (
          <InfoPage
            title="Liên Hệ Hỗ Trợ"
            subtitle="Cần giúp đỡ? Chúng tôi luôn sẵn sàng hỗ trợ bạn nhanh chóng."
            sections={[
              { heading: 'Hotline hỗ trợ', text: 'Gọi ngay 999.999.9999 để được hỗ trợ trực tiếp về đặt vé, combo và sự cố thanh toán.' },
              { heading: 'Email hỗ trợ', text: 'Gửi yêu cầu đến duongwnguyenx6@gmail.com. Chúng tôi sẽ trả lời bạn trong vòng 24 giờ.' },
              { heading: 'Thời gian phục vụ', text: 'Bộ phận hỗ trợ hoạt động từ 08:00 đến 22:00 mỗi ngày. Ngoài giờ, bạn vẫn có thể gửi email và nhận phản hồi sớm nhất.' },
            ]}
            onBack={() => setCurrentScreen('movie-list')}
          />
        )}

        {currentScreen === 'terms' && (
          <InfoPage
            title="Điều Khoản Dịch Vụ"
            subtitle="Các điều khoản quan trọng khi sử dụng dịch vụ CinemaHub."
            sections={[
              { heading: 'Đặt vé và hoàn vé', text: 'Vé mua qua ứng dụng được xem là hợp lệ khi thanh toán thành công. Hoàn vé chỉ áp dụng theo chính sách của rạp và suất chiếu.' },
              { heading: 'Quyền sử dụng', text: 'CinemaHub có quyền thay đổi nội dung, giá vé và các chương trình khuyến mãi mà không cần báo trước.' },
              { heading: 'Trách nhiệm', text: 'Người dùng chịu trách nhiệm bảo mật thông tin cá nhân và thông tin tài khoản. Mọi hành vi vi phạm sẽ bị xử lý theo quy định.' },
            ]}
            onBack={() => setCurrentScreen('movie-list')}
          />
        )}

        {currentScreen === 'privacy' && (
          <InfoPage
            title="Chính Sách Riêng Tư"
            subtitle="Cách chúng tôi thu thập, lưu trữ và bảo vệ thông tin của bạn."
            sections={[
              { heading: 'Dữ liệu cá nhân', text: 'Chúng tôi lưu thông tin cơ bản như tên, email và lịch sử đặt vé để cải thiện trải nghiệm sử dụng.' },
              { heading: 'Bảo mật', text: 'Thông tin của bạn được bảo vệ bằng các biện pháp kỹ thuật. Chúng tôi không chia sẻ dữ liệu cho bên thứ ba trái phép.' },
              { heading: 'Quyền người dùng', text: 'Bạn có quyền yêu cầu xem, chỉnh sửa hoặc xóa dữ liệu cá nhân theo quy định hiện hành.' },
            ]}
            onBack={() => setCurrentScreen('movie-list')}
          />
        )}

        {currentScreen === 'admin' && currentUser && currentUser.role === 'admin' && (
          adminView === 'panel' ? (
            <AdminPanel
              users={users}
              movies={movies}
              showtimes={showtimes}
              rooms={rooms}
              bookings={bookings}
              onCancelBooking={handleCancelBooking}
              onCancelOrder={handleCancelOrder}
              onAddShowtime={handleAddShowtime}
              onBackHome={() => setCurrentScreen('movie-list')}
              onManageMovies={() => setAdminView('movies')}
            />
          ) : (
            <MovieManagement
              movies={movies}
              showtimes={showtimes}
              onCreateMovie={(m) => setMovies((prev) => [...prev, m])}
              onUpdateMovie={(m) => setMovies((prev) => prev.map(x => (String(x.id) === String(m.id) ? m : x)))}
              onDeleteMovie={(id) => setMovies((prev) => prev.filter(x => String(x.id) !== String(id)))}
              onBack={() => setAdminView('panel')}
            />
          )
        )}

        {currentScreen === 'auth' && (
          <AuthScreen
            users={users}
            onLogin={handleLogin}
            onRegister={handleRegister}
            onForgotPassword={handleForgotPassword}
            mode={authMode}
            onSwitchMode={setAuthMode}
            statusMessage={statusMessage}
            onBack={() => setCurrentScreen('movie-list')}
          />
        )}
      </div>
    </div>
  );
}

export default App;
